#!/usr/bin/env python3
"""Freeze a long-only failed-breakdown reclaim grid before the historical replay."""
import hashlib,json,subprocess,sys
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];R=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'research/automation'));import registry
DATA={a:[ROOT/f'data/normalized/binance/{a}/binance_{a}_20240916T000000Z_20250916T000000Z_transfer_20261001/spot_bars.parquet',ROOT/f'data/normalized/binance/{a}/binance_{a}_20250916T000000Z_20260916T000000Z_archive_20260929/spot_bars.parquet'] for a in ('BTC','ETH')}
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def utc():return datetime.now(timezone.utc).isoformat().replace('+00:00','Z')
start='2025-09-19T00:01:00Z';end='2026-09-14T00:01:00Z';raw=R/'exchange_info_raw.json';meta=json.loads(raw.read_text())
assert {s['symbol'] for s in meta['symbols']}=={'BTCUSDT','ETHUSDT'} and all(s['status']=='TRADING' and s.get('isSpotTradingAllowed',True) for s in meta['symbols'])
assets={a:[{'path':str(p.relative_to(ROOT)),'sha256':sha(p),'bytes':p.stat().st_size} for p in ps] for a,ps in DATA.items()}
logic={
 'setup':'At completed UTC daily close t, when flat and no setup is pending, arm a failed-breakdown setup only if close[t] is strictly below lower[t]=min(low[t-N:t]); the N prior completed daily bars exclude t. Store that exact lower level and expiry day index t+K.',
 'reclaim':'On one of the next K completed daily closes after the breakdown day (inclusive of day t+K), if close[j] is strictly above the stored lower[t], enter long at the next UTC day 00:01 1-minute bar open. A reclaim on breakdown day itself is not allowed. While pending, ignore any subsequent new lows and retain the first broken level. If K days pass without reclaim, disarm after the expiry day close; a new breakdown may arm from the following closed day.',
 'hold_exit':'Hold exactly H=5 elapsed UTC daily intervals from virtual entry timestamp; exit at the 00:01 UTC minute open after five full closed daily bars. Ignore all new breakdown/reclaim signals while holding and on the exit event day; setup processing resumes the next UTC daily decision. No stop, profit target or overlapping positions.',
 'sizing':'One 2,000-USDT portfolio with separate BTC and ETH long-only cash sleeves; raw initial weights 0.50/0.50 (1,000 USDT each). Each signal uses its sleeve only; no cross-sleeve transfers/rebalancing, leverage, shorting or cash interest. Full available sleeve cash is allocated at entry; full units sold at exit.',
 'timing':'Only fully closed UTC daily OHLC bars can arm, reclaim or exit. Daily close becomes available at next UTC 00:00; simulated order reference is the following 00:01 1-minute open, 60 seconds later. Warmup data may form the prior N-day levels, but there are no pre-OOS positions. OOS begins 2025-09-19 00:01 UTC and terminal liquidation is 2026-09-14 00:01 UTC.',
 'channel_extrema':'Prior-low calculation excludes the compared day. Reclaim compares against the saved breakdown-day lower level, not a moving later channel.'}
costs={'fee_per_side':0.001,'estimated_half_spread_per_side':0.0001,'slippage_per_side':0.0002,'impact':'0.5 * sample stdev of prior 20 fully closed daily log returns * sqrt(order quote budget / mean quote volume over prior 20 complete UTC days)','maximum_ADV_participation':0.001,'multipliers':[1,2,3],'all_cost_terms_scaled_together':True,'cash_yield':0}
plan={'round':R.name,'frozen_at_utc':utc(),'status':'frozen_before_evaluation','source_repository_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'direction':'Long-only failed-breakdown reclaim with a fixed five-day holding period','hypothesis':'Some breaks below an established N-day low may reverse within the next K closes; entering only after a completed close reclaims the broken level may capture rebounds without buying the initial breakdown. This is a predeclared countertrend hypothesis, not a claim of an exact reproduction of the published Turtle Soup setup.', 'literature_context':[{'source':'Linda Bradford Raschke official recommended-reading list, which lists Street Smarts coauthored with Laurence A. Connors','url':'https://lindaraschke.net/recommended-reading/','accessed_utc':utc(),'scope':'Bibliographic origin context only; the evaluated rule below is our explicitly fixed long-only daily adaptation, not the authors’ complete setup or proof of crypto profitability.'},{'source':'Turtle Soup historical rule summary','url':'https://www.turtletrader.com/trader-raschke/','accessed_utc':utc(),'scope':'Secondary historical description of fading failed channel breaks; used only to motivate the idea, not as performance evidence.'}], 'prior_work':{'initial16_audit':'research/experiments/20261012T035429Z/prior_evidence_audit.json found actual backtest evidence for all sixteen initial entries; no initial code-only configuration is eligible for backfill.','unavailable_registry_rows':'58 unresolved latest definitions are 40 blocked btc-eth-2 paper-live observations and 18 abandoned superseded lead-lag drafts; these are not missing initial research backtests and are left unchanged.','adjacent_work':'Daily RSI2 reversion, ratio z-score mean reversion, long-horizon relative strength, hourly lead-lag, volatility compression and channel breakout families have stored results. This grid changes the event to a one-shot close reclaim of the specific level broken earlier; it remains related countertrend research and shares repeated historical selection risk.','history_note':'2025-09-19..2026-09-14 is repeatedly reused development/OOS history, not an untouched final holdout.'},'data':{'exchange':'Binance spot archived 1-minute OHLCV aggregated into continuous UTC daily OHLCV. Execution uses the exact following-day 00:01 1m open from the same real archived data; no earlier or later bar is selected.','assets':assets,'exchange_info_raw_path':str(raw.relative_to(ROOT)),'exchange_info_raw_sha256':sha(raw),'start_utc':start,'end_exclusive_utc':end,'oos_days':360,'folds':12,'fold_days':30,'history_reused':True},'portfolio':{'capital_usdt':2000,'initial_capital_usdt':2000,'raw_initial_weights':{'BTC':0.5,'ETH':0.5},'raw_asset_weights':[0.5,0.5],'sleeve_cash_usdt':{'BTC':1000,'ETH':1000},'transfer':False,'leverage':False},'rule':logic,'grid':{'breakdown_lookback_days':[10,20,40],'reclaim_window_days':[1,2,3],'fixed_holding_days':5,'assets':['BTC','ETH'],'sensitivity':'Full 3x3 grid over N-day prior-low setup lookback and K-day reclaim window; all combinations retained.'},'cost_model':costs,'exchange_snapshot':{'captured_server_time_ms':meta.get('serverTime'),'raw_sha256':sha(raw),'filters':['PRICE_FILTER','LOT_SIZE','NOTIONAL','PERCENT_PRICE_BY_SIDE'],'percent_price_reference':'Historical order filters use mean of prior five complete 1m closes as a proxy for the current avgPriceMins reference; exact historical exchange rule and book snapshots are unavailable.'},'time_splits':{'oos_start_utc':start,'oos_end_exclusive_utc':end,'folds':12,'fold_days':30,'contiguous':True,'signal_uses_only_closed_bars':True},'failure_gates':{'all_1x_2x_3x_net_returns_positive':True,'positive_1x_folds_minimum':8,'folds':12,'maximum_3x_sampled_drawdown_pct':25,'minimum_3x_local_neighbor_positive_fraction':0.60,'minimum_gross_to_cost':2.5,'zero_capacity_or_exchange_filter_rejections':True,'terminal_flat_all_cost_scenes':True},'benchmark_read_only':{'source_report':'research/experiments/20261013T224056Z/report.json','configuration':'hold_360d_BTC_ETH_50_50_monthly_volmanaged','note':'Read-only same 360-day start/end, separate 1,000-USDT BTC/ETH initial sleeves and cost scenes; do not recalculate this exact benchmark.'},'prior_registry_snapshot':{'events_before_batch':9474,'unique_fingerprints_before_batch':4633}}
plan['_sha256']=registry.digest(plan);(R/'plan.json').write_text(json.dumps(plan,indent=2,ensure_ascii=False)+'\n')
batch=[];prior=registry.read_records(ROOT/'research/automation/registry.jsonl');seen=set()
for n in (10,20,40):
 for k in (1,2,3):
  name=f'failed_breakdown_N{n}_K{k}_H5'
  parameters={'breakdown_lookback_days':n,'reclaim_window_days':k,'fixed_holding_days':5,'capital_usdt':2000,'initial_capital_usdt':2000,'raw_initial_weights':{'BTC':0.5,'ETH':0.5},'raw_asset_weights':[0.5,0.5],'sleeve_cash_usdt':{'BTC':1000,'ETH':1000},'start_utc':start,'end_exclusive_utc':end,'folds':12,'fold_days':30,'fee_per_side':0.001,'estimated_half_spread_per_side':0.0001,'slippage_per_side':0.0002,'maximum_ADV_participation':0.001,'cost_multipliers':[1,2,3],'exchange_info_raw_sha256':sha(raw)}
  spec={'kind':'strategy','family':'spot-daily-failed-breakdown-reclaim-fixed-hold','market':'spot','universe':['BTC/USDT','ETH/USDT'],'timeframe':'1d','logic':logic,'parameters':parameters,'validation_plan':str((R/'plan.json').relative_to(ROOT)),'name':name}
  fp=registry.fingerprint(spec);assert fp not in seen and not (prior.get(fp) and prior[fp].get('result_available') is True),name;seen.add(fp)
  path=R/'specs'/(name+'.json');path.parent.mkdir(exist_ok=True);path.write_text(json.dumps(spec,indent=2,ensure_ascii=False)+'\n');batch.append({'name':name,'spec':str(path.relative_to(ROOT)),'role':'candidate'})
(R/'batch.json').write_text(json.dumps(batch,indent=2,ensure_ascii=False)+'\n')
print(json.dumps({'frozen':True,'plan_sha256':sha(R/'plan.json'),'candidate_configs':len(batch),'prior_events':plan['prior_registry_snapshot']['events_before_batch'],'prior_unique_fingerprints':plan['prior_registry_snapshot']['unique_fingerprints_before_batch'],'initial16_missing':0,'exact_duplicates':0}))
